DO $$ DECLARE v_def text; BEGIN SELECT pg_get_functiondef('public.dp_documento_requisitos_seed(uuid)'::regprocedure) INTO v_def; IF position('(_company_id,''autorizacao_judicial_menor''' IN v_def)=0 THEN RAISE EXCEPTION 'Lista padrao alterada: revisar'; END IF; v_def := regexp_replace(v_def, '\s*\(_company_id,\s*''autorizacao_judicial_menor''[^\n]*\n', E'\n', 'g'); EXECUTE v_def; END $$;